SELECT json_build_object(
 'columns',(SELECT json_agg(json_build_object('table',c.relname,'kind',c.relkind,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'has_default',d.oid IS NOT NULL OR a.attidentity<>'')) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','v') AND a.attnum>0 AND NOT a.attisdropped),
 'enums',(SELECT json_object_agg(t.typname,(SELECT json_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e'),
 'relationships',(SELECT json_agg(json_build_object('table',c.relname,'name',f.conname,'columns',(SELECT json_agg(a.attname ORDER BY k.ord) FROM unnest(f.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=f.conrelid AND a.attnum=k.num),'target',r.relname,'target_columns',(SELECT json_agg(a.attname ORDER BY k.ord) FROM unnest(f.confkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=f.confrelid AND a.attnum=k.num))) FROM pg_constraint f JOIN pg_class c ON c.oid=f.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_class r ON r.oid=f.confrelid JOIN pg_namespace rn ON rn.oid=r.relnamespace WHERE f.contype='f' AND n.nspname='public' AND rn.nspname='public'),
 'functions',(SELECT json_agg(json_build_object('name',p.proname,'return',pg_get_function_result(p.oid),'args',(SELECT json_agg(json_build_object('name',p.proargnames[k.ord],'type',format_type(k.typ,NULL),'optional',k.ord>p.pronargs-p.pronargdefaults) ORDER BY k.ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY k(typ,ord)))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.prorettype<>'trigger'::regtype)
);
